          { partName: "Engine Air Filter", category: "Maintenance", oem: { brand: "BMW Genuine", code: "13718605164", approxPrice: "35 EUR" }, crossRef: { brand: "Mahle", code: "LX 2077/4", approxPrice: "20 EUR", source: "OEM Supplier", autodoclink: "https://www.autodoc.co.uk", advanceautopartslink: "https://shop.advanceautoparts.com" }, note: "Panel filter." }
