  engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with arc-sprayed cylinder bores (LDS). The B47 TU1 revision is a masterpiece of diesel engineering, featuring a completely redesigned timing drive at the rear that eliminates the fatal N47 flaw. The LCI pairs this with a 48V Mild-Hybrid starter-generator for seamless start-stop and torque fill.", crankshaft: "Forged Steel, supported by 5 main bearings. Exceptionally strong, paired with twin balance shafts to eliminate 4-cylinder vibrations.", pistonSpeed: "13.3 m/s @ 4000 RPM.", alternator: "48V Starter-Generator unit.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with specific bowls optimized for Common Rail injection.", wristPinDiameter: "26 mm.", connectingRodLength: "136 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.51." }, cylinderHead: { combustionChamberVol: "Direct injection bowls in piston.", intakePortFlow: "16-valve DOHC design. The intake manifold features an integrated Swirl Flap mechanism.", valveSizes: "Intake: 26.0 mm / Exhaust: 26.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the robust rear-mounted timing chain.", lifterType: "Hydraulic Tappets with roller rocker arms.", specialFeature: "Bosch Common Rail Direct Injection. Fuel is stored at 2200 Bar, allowing the DDE to trigger multiple microscopic injection events for incredible smoothness." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven map-controlled variable displacement pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Coolant-to-oil heat exchanger mounted to the oil filter housing." }, fuelSystem: { systemType: "Bosch CP4 Common Rail High-Pressure Pump.", maxPressure: "2200 Bar.", injectors: "4x Bosch Solenoid Injectors." }, tuningLimits: { maxSafeTorqueStock: "550 Nm (Transmission limits).", maxSafePowerStock: "260 hp (Requires DPF modifications).", maxSafeRPM: "4800 RPM (Governed by DDE).", weakestLink: "Locked DME, CP4 Fuel Pump, EGR Cooler (Fire Risk), Vibration Damper." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE 8 (Encrypted LCI Unit)." } },
  recommendedParts: { description: "Crucial maintenance parts to keep the highly reliable B47 TU1 diesel running flawlessly.", parts: [ { category: "EGR Cooler (Recall Revision)", brand: "BorgWarner", note: "CRITICAL: Check recall status immediately to prevent fire risk." }, { category: "Intake Manifold Assembly", brand: "Genuine BMW", note: "Replace if swirl flaps are heavily coked or the plastic is melted." }, { category: "Glow Plugs & Module", brand: "Bosch", note: "Replace all 4 proactively to ensure DPF regenerations occur." }, { category: "DPF Pressure Sensor", brand: "Bosch", note: "CRITICAL: Fails and stops DPF regen, eventually ruining the exhaust." }, { category: "Vibration Damper", brand: "Corteco", note: "Replace proactively if rubber cracking is visible." }, { category: "Diesel Fuel Filter", brand: "Mann-Filter", note: "CRITICAL: Change every 30k km to protect the CP4 Common Rail pump." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Cartridge style. Change oil religiously at 10k km." }, { category: "Water Pump", brand: "Saleri", note: "Mechanical pump on the B47. Replace proactively over 150k km." } ] },
