    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 Synthetic. Frequent oil changes are vital for the B47 TU1.", parts: ["5.0L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "70 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "25 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Diesel Fuel Filter", details: "CRITICAL: Replace the high-pressure fuel filter to protect the CP4 pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "30 EUR" } ],
