  engineeringData: { blockDesign: "Closed-deck Aluminum alloy block with arc-sprayed cylinder bores (LDS). The B57 is a 3.0L inline-6 masterpiece, offering unparalleled smoothness and structural rigidity. The O1 variant upgrades to sequential twin-turbos and pairs with a 48V Mild-Hybrid starter-generator for seamless start-stop and torque fill.", crankshaft: "Forged Steel, supported by 7 main bearings. Exceptionally strong, perfectly balanced naturally due to the inline-6 layout, requiring no balance shafts.", pistonSpeed: "15.0 m/s @ 4000 RPM.", alternator: "48V Starter-Generator unit.", rotatingAssembly: { pistonConstruction: "Cast Aluminum alloy with specific bowls optimized for Common Rail injection.", wristPinDiameter: "30 mm.", connectingRodLength: "136 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.51." }, cylinderHead: { combustionChamberVol: "Direct injection bowls in piston.", intakePortFlow: "24-valve DOHC design. The intake manifold features an integrated Swirl Flap mechanism.", valveSizes: "Intake: 27.0 mm / Exhaust: 27.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the robust rear-mounted timing chain.", lifterType: "Hydraulic Tappets with roller rocker arms.", specialFeature: "Bosch Common Rail Direct Injection. Fuel is stored at 2500 Bar, allowing the DDE to trigger multiple microscopic injection events for incredible smoothness." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Chain-driven map-controlled variable displacement pump.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Massive Coolant-to-oil heat exchanger mounted to the oil filter housing." }, fuelSystem: { systemType: "Bosch Heavy-Duty Common Rail High-Pressure Pump.", maxPressure: "2500 Bar.", injectors: "6x Bosch Piezo Injectors." }, tuningLimits: { maxSafeTorqueStock: "750 Nm (Transmission limits).", maxSafePowerStock: "370 hp (Requires DPF modifications).", maxSafeRPM: "4800 RPM (Governed by DDE).", weakestLink: "Locked DME, EGR Cooler (Fire Risk), Vibration Damper, DPF Flow Limits." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE 8 (Encrypted LCI Unit)." } },
  recommendedParts: { description: "Crucial maintenance parts to keep the legendary B57 inline-6 diesel running flawlessly.", parts: [ { category: "EGR Cooler (Recall Revision)", brand: "BorgWarner", note: "CRITICAL: Check recall status immediately to prevent fire risk." }, { category: "Intake Manifold Assembly", brand: "Genuine BMW", note: "Replace if swirl flaps are heavily coked or the plastic is melted." }, { category: "Glow Plugs & Module", brand: "Bosch", note: "Replace all 6 proactively to ensure DPF regenerations occur." }, { category: "DPF Pressure Sensor", brand: "Bosch", note: "CRITICAL: Fails and stops DPF regen, eventually ruining the exhaust." }, { category: "Vibration Damper", brand: "Corteco", note: "Replace proactively if rubber cracking is visible." }, { category: "Diesel Fuel Filter", brand: "Mann-Filter", note: "CRITICAL: Change every 30k km to protect the high-pressure pump." }, { category: "Engine Oil Filter", brand: "Mann-Filter", note: "Cartridge style. Change oil religiously at 10k km." }, { category: "Water Pump", brand: "Saleri", note: "Mechanical pump on the B57. Replace proactively over 150k km." } ] },
