    oilAndFilters: [ { interval: "10,000 km", timeLimit: "1 year", task: "Oil & Filter Change", details: "CRITICAL: Use high-quality 5W-30 Synthetic. Frequent oil changes are vital for the B57.", parts: ["6.5L 5W-30", "Mann Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "85 EUR" }, { interval: "20,000 km", timeLimit: "2 years", task: "Engine Air Filter", details: "Replace the panel paper filter element.", parts: ["Air Filter"], importance: "High", laborDifficulty: "Easy", estimatedCost: "30 EUR" }, { interval: "30,000 km", timeLimit: "3 years", task: "Diesel Fuel Filter", details: "CRITICAL: Replace the high-pressure fuel filter to protect the pump.", parts: ["Fuel Filter"], importance: "Critical", laborDifficulty: "Easy", estimatedCost: "35 EUR" } ],
    ignitionAndEngine: [ { interval: "Immediately", timeLimit: "Unlimited", task: "EGR Cooler Recall Verification", details: "CRITICAL: Contact BMW to ensure the fire-risk recall has been done.", parts: ["Dealership Service"], importance: "Critical", laborDifficulty: "Expert", estimatedCost: "0 EUR (Recall)" }, { interval: "60,000 km", timeLimit: "5 years", task: "Glow Plugs & Module", details: "Replace all 6 glow plugs and the module proactively.", parts: ["6x Glow Plugs", "Module"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }, { interval: "100,000 km", timeLimit: "Unlimited", task: "Intake Manifold Decarbonization", details: "Remove and clean the manifold and swirl flaps.", parts: ["Intake Gasket Set"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "150 EUR" } ],
